// debug context:start
console.debug('context:', context);
// debug context: end

// variable load
const timeRange = context.panel.data.timeRange;
const timeRangeFrom = timeRange?.from?.valueOf();
const timeRangeTo = timeRange?.to?.valueOf();
console.debug('timeRange:', timeRangeFrom, timeRangeTo);

/**
 * status 에 따라 legent, data 시각화
 */
const _status = {
  "2xx": {
    name: "2xx",
    color: "#4CAF50",
    chart: {
      type: "scatter",
      symbolSize: 5,
      itemStyle: { color: "#4CAF50", opacity: 0.66 }
    },
  },
  "3xx": {
    name: "3xx",
    color: "#4CAF50",
    chart: {
      type: "scatter",
      symbolSize: 5,
      itemStyle: { color: "#4CAF50", opacity: 0.66 }
    },
  },
  "4xx": {
    name: "4xx",
    color: "#f4e736",
    chart: {
      type: "scatter",
      symbolSize: 5,
      itemStyle: { color: "#f4e736", opacity: 0.66 }
    },
  },
  "5xx": {
    name: "5xx",
    color: "#F44336",
    chart: {
      type: "scatter",
      symbolSize: 5,
      itemStyle: { color: "#F44336", opacity: 0.66 }
    },
  },
  "other": {
    name: "other",
    color: "#4FC3F7",
    chart: {
      type: "scatter",
      symbolSize: 5,
      itemStyle: { color: "#4FC3F7", opacity: 0.66 }
    },
  }
}

// Trace 정보 추출
const traceFrame = context.panel.data.series[0];
if (!traceFrame || !traceFrame.fields.length) {
  return { title: { text: '데이터 없음', left: 'center', top: 'center' } };
}

const getTraceField = (name) => traceFrame.fields.find(f => f.name === name);

const traceIdField = getTraceField('traceID');
const startTimeField = getTraceField('startTime');
const serviceField = getTraceField('traceService');
const nameField = getTraceField('traceName');
const nestedField = getTraceField('nested');

const points = (startTimeField?.values ?? []).map((t, i) => {
  const traceId = traceIdField?.values[i] ?? '';
  const service = serviceField?.values[i] ?? '';
  const name = nameField?.values[i] ?? traceId;

  // Root Span 정보 추출
  const spanFrames = nestedField?.values[i]
  const rootSpanFrame = spanFrames?.[0];
  const rootSpanFields = rootSpanFrame?.fields ?? [];
  const getRootSpanField = (n) => rootSpanFields.find(f => f.name === n)?.values[0];

  const duration = getRootSpanField('duration') ?? 0;
  const httpStatusCode = getRootSpanField('http.response.status_code') ?? getRootSpanField('http.status_code')

  let status = "other"
  if (httpStatusCode < 300) status = "2xx"
  else if (httpStatusCode < 400) status = "3xx"
  else if (httpStatusCode < 500) status = "4xx"
  else if (httpStatusCode < 600) status = "5xx"

  const points = {
    value: [t, duration / 1_000_000],
    traceId, name, service, status,
    itemStyle: _status[status].chart.itemStyle,
  };

  console.debug("points=", points);
  return points;
});


// 클릭 이벤트 등록                                                                                                                                                                                       
const chart = context.panel.chart;
if (chart) {
  chart.off('click');
  chart.on('click', (params) => {
    const traceId = params.data?.traceId;
    if (!traceId) return;

    // 클릭한 trace 시간 기준 ±30분                                                                                                                                                                         
    const startTime = params.data?.value[0];
    const from = startTime - 30 * 60 * 1000;
    const to = startTime + 30 * 60 * 1000;

    const query = JSON.stringify({
      datasource: 'tempo',
      queries: [{ query: traceId, queryType: 'traceql' }],
      range: { from: String(from), to: String(to) },
    });

    chart.dispatchAction({
      type: 'brush',
      command: 'clear', // 모든 브러시 영역 삭제
      areas: []         // 영역 배열을 비움
    });

    window.open(`/explore?orgId=1&left=${encodeURIComponent(query)}`, '_blank');
  });
}


// 드래그 이벤트 등록 - 기존 click 이벤트 아래에 추가
chart.off('brushSelected');
chart.on('brushSelected', (params) => {
  const selected = params.batch?.[0]?.selected ?? [];
  const traceIds = [];
  console.debug("selected=", selected)

  selected.forEach((s) => {
    s.dataIndex.forEach((idx) => {
      const seriesData = chart.getOption().series[s.seriesIndex]?.data;
      console.debug("selected seriesData=", seriesData)

      const traceId = seriesData?.[idx]?.traceId;
      if (traceId) traceIds.push(traceId);
    });
  });
  console.debug("selected traceIds=", traceIds)

  if (traceIds.length === 0) return;

  // TraceQL 쿼리 생성
  const traceQL = traceIds.map(id => `{ trace:id="${id}" }`).join(' || ');
  const left = JSON.stringify({
    datasource: 'tempo',
    queries: [{ query: traceQL, queryType: 'traceql' }],
    range: { from: 'now-1h', to: 'now' },
  });

  // 브러시 선택 제거
  chart.dispatchAction({ type: 'brush', command: 'clear', areas: [] });

  window.open(`/explore?orgId=1&left=${encodeURIComponent(left)}`, '_blank');
});


return {
  backgroundColor: 'transparent',
  tooltip: {
    trigger: 'item',
    formatter: (p) => {
      const d = p.data;
      return [
        `<b>${d.name}</b>`,
        `Service: ${d.service}`,
        `Time: ${new Date(d.value[0]).toLocaleTimeString()}`,
        `Duration: ${d.value[1]} mssss`,
        `Status: ${d.status}`,
        `TraceID: ${d.traceId.substring(0, 16)}...`,
        `<a href="http://google.com">Trace 확인</a>`
      ].join('<br/>');
    },
  },
  toolbox: {
    feature: {
      brush: {
        type: ['rect'],
        title: { rect: '드래그 선택' },
      },
    },
    right: 10,
    top: 0,
  },
  brush: {
    toolbox: ['rect'],
    xAxisIndex: 0,
    throttleType: 'debounce',
    throttleDelay: 300,
    outOfBrush: { colorAlpha: 0.2 },  // 선택 안 된 포인트 흐리게
  },
  xAxis: { type: 'time', name: 'Time', nameLocation: 'end', min: timeRangeFrom, max: timeRangeTo },
  yAxis: { type: 'value', name: 'Duration (ms)', nameLocation: 'end', min: 0 },
  legend: {
    data: Object.values(_status).map(_value => _value.name),
    right: 50
  },
  series: Object.entries(_status).map(([_key, _value]) => ({
    name: _value.name,
    data: points.filter(p => p.status == _key),
    ..._value.chart
  }))
};
